/// <summary>
/// Data contract for message types
/// </summary>
[DataContractAttribute]
class OMGProcessingContract
{
    OMGMessageTypeId    messageTypeId;
    container           recordContainer;

}

Method.Source:
[DataMember]
public OMGMessageTypeId parmMessageTypeId(OMGMessageTypeId _messageTypeId = messageTypeId)
{
    messageTypeId = _messageTypeId;
    return messageTypeId;
}

[DataMember]
public container parmRecordContainer(container _recordContainer = recordContainer)
{
    recordContainer = _recordContainer;

    return recordContainer;
}
